package com.fream.back.domain.faq.repository;

import com.fream.back.domain.faq.dto.FaqBidResponseDto;
import com.fream.back.domain.faq.dto.FaqBidStatusCountDto;
import com.fream.back.domain.faq.entity.BidStatus;
import com.fream.back.domain.faq.entity.QFaq;
import com.fream.back.domain.faq.entity.QFaqBid;
import com.fream.back.domain.user.entity.QUser;
import com.fream.back.domain.user.entity.QUserColor;
import com.fream.back.domain.user.entity.QUserImage;
import com.fream.back.domain.user.entity.QUserSize;
import com.fream.back.domain.address.entity.QFaqAddress;
import com.fream.back.domain.product.entity.QProduct;
import com.querydsl.core.BooleanBuilder;
import com.querydsl.core.Tuple;
import com.querydsl.core.types.Projections;
import com.querydsl.jpa.impl.JPAQueryFactory;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Repository;
import org.springframework.util.StringUtils;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;




@Repository
@RequiredArgsConstructor
public class FaqBidRepositoryImpl implements FaqBidRepositoryCustom {
    private final JPAQueryFactory queryFactory;

    @Override
    public Page<FaqBidResponseDto> findOrderBidsByFilters(String email, String bidStatus, String orderStatus, Pageable pageable) {
        QFaqBid orderBid = QFaqBid.faqBid;
        QFaq order = QFaq.faq;
        QUserSize productSize = QUserSize.userSize;
        QUserColor productColor = QUserColor.userColor;
        QUser product = QUser.user;
        QUserImage productImage = QUserImage.userImage;
        QFaqAddress orderShipment = QFaqAddress.faqAddress;
        QProduct user = QProduct.product;


        BooleanBuilder whereBuilder = new BooleanBuilder();


        if (StringUtils.hasText(email)) {
            whereBuilder.and(user.email.eq(email));
        }


        if (StringUtils.hasText(bidStatus)) {
            whereBuilder.and(orderBid.status.stringValue().eq(bidStatus));
        }


        if (StringUtils.hasText(orderStatus)) {
            whereBuilder.and(order.status.stringValue().eq(orderStatus));
        }


        List<FaqBidResponseDto> content = queryFactory
                .select(Projections.constructor(
                        FaqBidResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(whereBuilder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory
                .select(orderBid.id.count())
                .from(orderBid)
                .join(orderBid.user, user)
                .leftJoin(orderBid.order, order)
                .where(whereBuilder)
                .fetchOne();

        return new PageImpl<>(content, pageable, total != null ? total : 0L);
    }

    @Override
    public FaqBidStatusCountDto countOrderBidsByStatus(String email) {
        QFaqBid orderBid = QFaqBid.faqBid;


        Long pendingCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(BidStatus.PENDING)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long matchedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(BidStatus.MATCHED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long cancelledOrCompletedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.in(
                                BidStatus.CANCELLED, BidStatus.COMPLETED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        pendingCount = pendingCount != null ? pendingCount : 0L;
        matchedCount = matchedCount != null ? matchedCount : 0L;
        cancelledOrCompletedCount = cancelledOrCompletedCount != null ? cancelledOrCompletedCount : 0L;

        return new FaqBidStatusCountDto(pendingCount, matchedCount, cancelledOrCompletedCount);
    }

    @Override
    public FaqBidResponseDto findOrderBidById(Long orderBidId, String email) {
        QFaqBid orderBid = QFaqBid.faqBid;
        QFaq order = QFaq.faq;
        QUserSize productSize = QUserSize.userSize;
        QUserColor productColor = QUserColor.userColor;
        QUser product = QUser.user;
        QUserImage productImage = QUserImage.userImage;
        QFaqAddress orderShipment = QFaqAddress.faqAddress;
        QProduct user = QProduct.product;

        return queryFactory
                .select(Projections.constructor(
                        FaqBidResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(
                        orderBid.id.eq(orderBidId),
                        orderBid.user.email.eq(email)
                )
                .fetchOne();
    }

    @Override
    public Map<Long, Long> tradeCountByColorIds(List<Long> colorIds) {
        if (colorIds == null || colorIds.isEmpty()) {
            return Collections.emptyMap();
        }

        QFaqBid orderBid = QFaqBid.faqBid;
        QUserSize productSize = QUserSize.userSize;

        List<Tuple> results = queryFactory.select(
                        productSize.productColor.id,
                        orderBid.id.count()
                )
                .from(orderBid)
                .join(orderBid.productSize, productSize)
                .where(
                        productSize.productColor.id.in(colorIds),
                        orderBid.status.eq(BidStatus.COMPLETED)
                )
                .groupBy(productSize.productColor.id)
                .fetch();

        return results.stream()
                .collect(Collectors.toMap(
                        t -> t.get(productSize.productColor.id),
                        t -> t.get(orderBid.id.count())
                ));
    }
