public Page<UserSearchResponseDto> searchProducts(
        String keyword,
        List<Long> categoryIds,
        List<GenderType> genders,
        List<Long> brandIds,
        List<Long> collectionIds,
        List<String> colors,
        List<String> sizes,
        Integer minPrice,
        Integer maxPrice,
        SortOption sortOption,
        Pageable pageable) {

    QUser product = QUser.user;
    QUserColor productColor = QUserColor.userColor;
    QUserSize productSize = QUserSize.userSize;
    QInterest interest = QInterest.interest;
    QBrand brand = QBrand.brand;

    System.out.println("Keyword: " + keyword);
    System.out.println("Category IDs: " + categoryIds);
    System.out.println("Genders: " + genders);
    System.out.println("Brand IDs: " + brandIds);
    System.out.println("Collection IDs: " + collectionIds);
    System.out.println("Colors: " + colors);
    System.out.println("Sizes: " + sizes);
    System.out.println("Min Price: " + minPrice);
    System.out.println("Max Price: " + maxPrice);


    JPQLQuery<Tuple> query = queryFactory.select(
                    product.id,
                    product.name,
                    product.englishName,
                    product.releasePrice,
                    productColor.id,
                    productColor.colorName,
                    productColor.thumbnailImage.imageUrl,
                    productSize.purchasePrice.min(),
                    interest.count(),
                    product.brand.name
            )
            .from(product)
            .leftJoin(product.colors, productColor)
            .leftJoin(product.brand, brand)
            .leftJoin(productColor.thumbnailImage, QUserImage.userImage)
            .leftJoin(productColor.sizes, productSize)
            .leftJoin(productColor.interests, interest)
            .where(
